<script lang="ts">
  import { t, locale } from '../i18n';
  import { liveValue } from './live-value';
  export interface Variable { name: string; expression: string; error?: string; title?: string }
  let { variables }: { variables: Variable[] } = $props();
  let exprHint = $derived(t('vars.exprHint', 'Any Geometry field takes an expression over these and over objects named in Layers: {examples}.', {}, $locale).split('{examples}'));
</script>
<div class="sec" id="varSec"><div class="sec-title">{t("ui.variables", "Variables", {}, $locale)}</div>{#each variables as variable}<div class="row var"><input type="text" class="vname" data-vname={variable.name} {@attach liveValue(variable.name)} spellcheck="false" autocomplete="off" aria-label={t("ui.variable.name", "Variable name", {}, $locale)}><div class="ctl"><input type="text" data-vexpr={variable.name} {@attach liveValue(variable.expression)} class={'geomin' + (variable.error ? ' bad' : '')} spellcheck="false" autocomplete="off" aria-label={t('vars.valueOf', 'Value of {name}', { name: variable.name }, $locale)} title={variable.title}></div><button class="icon flat vdel" data-vdel={variable.name} title={t("ui.delete.variable", "Delete Variable", {}, $locale)} aria-label={t('vars.deleteOf', 'Delete variable {name}', { name: variable.name }, $locale)}><svg viewBox="0 0 20 20"><path d="M5.5 5.5l9 9M14.5 5.5l-9 9"/></svg></button></div>{/each}<div class="btns"><button data-act="var:add">{t("ui.add.variable", "Add Variable", {}, $locale)}</button></div><div class="hint-line">{exprHint[0]}<code>w/2</code>, <code>a.east.x + gap</code>, <code>a.r * 2</code>, <code>dist(a, b)</code>{exprHint[1]} {t("vars.exportValues", "The export writes the values.", {}, $locale)}</div></div>
